package com.campusradar.accountdata;

import com.campusradar.common.*;
import com.campusradar.resume.PrivateFileStorage;
import com.campusradar.task.TaskHandler;
import java.nio.file.Path;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Component;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static com.campusradar.common.SqlRows.map;

@Component
public class AccountDataTasks implements TaskHandler {
    private final SqlRows rows;private final PrivateSnapshot snapshots;private final AccountDataService service;private final BackupCodec codec;private final PrivateFileStorage storage;private final Clock clock;private final TransactionTemplate tx;
    public AccountDataTasks(SqlRows rows,PrivateSnapshot snapshots,AccountDataService service,BackupCodec codec,PrivateFileStorage storage,Clock clock,PlatformTransactionManager manager){this.rows=rows;this.snapshots=snapshots;this.service=service;this.codec=codec;this.storage=storage;this.clock=clock;tx=new TransactionTemplate(manager);}
    public boolean supports(String type){return Set.of("DATA_EXPORT","DATA_IMPORT","USER_ERASURE").contains(type);}
    public String execute(String type,String owner,Map<String,Object> payload){if(Boolean.TRUE.equals(payload.get("accountDataApplied"))){tx.executeWithoutResult(s->lease(owner,payload));return null;}return switch(type){case "DATA_EXPORT"->export(owner,payload);case "DATA_IMPORT"->restore(owner,payload);case "USER_ERASURE"->erase(owner,payload);default->throw new ApiProblem(422,"VALIDATION_ERROR","任务类型无效。");};}
    @Override public void onTerminalFailure(String type,String owner,Map<String,Object> payload){if("DATA_IMPORT".equals(type)&&owner!=null&&payload.get("previewId")!=null)rows.db.update("UPDATE import_previews SET state='INVALID',version=version+1 WHERE user_id=:u AND id=:id AND state='APPLYING'",map("u",owner,"id",payload.get("previewId")));}
    /** users first, then the task lease: a reclaimed worker cannot commit a stale mutation. */
    private Map<String,Object> lease(String owner,Map<String,Object> payload){if(!payload.containsKey("taskId")||!payload.containsKey("leaseToken"))throw stale();if(owner!=null)rows.query("SELECT id FROM users WHERE id=:u FOR UPDATE",Map.of("u",owner));var task=rows.one("SELECT user_id,state,lease_token,lease_until,result_file_id FROM tasks WHERE id=:id FOR UPDATE",map("id",payload.get("taskId")),Set.of(),Set.of());if(!"RUNNING".equals(task.get("state"))||!Objects.equals(payload.get("leaseToken"),task.get("leaseToken"))||task.get("leaseUntil")==null||!Instant.parse(task.get("leaseUntil").toString()).isAfter(clock.instant())||(!Objects.equals(owner,task.get("userId"))&&!(task.get("userId")==null&&Boolean.TRUE.equals(payload.get("accountDataApplied")))))throw stale();return task;}
    private static ApiProblem stale(){return new ApiProblem(409,"TASK_LEASE_LOST","任务租约已失效。");}
    private void applied(String owner,Map<String,Object> payload){var saved=new LinkedHashMap<>(payload);saved.remove("taskId");saved.remove("leaseToken");saved.put("accountDataApplied",true);rows.db.update("UPDATE tasks SET payload=:payload WHERE id=:id AND lease_token=:lease",map("id",payload.get("taskId"),"lease",payload.get("leaseToken"),"payload",rows.json.writeValueAsString(saved)));}
    private String export(String owner,Map<String,Object> payload){String existing=tx.execute(s->{var task=lease(owner,payload);return Objects.toString(task.get("resultFileId"),null);});if(existing!=null)return existing;
        var captured=snapshots.capture(owner);boolean originals=Boolean.TRUE.equals(payload.get("includeFiles"));if(originals&&captured.storage().values().stream().mapToLong(f->((Number)f.get("sizeBytes")).longValue()).sum()>BackupCodec.MAX_EXPANDED-11L*1024*1024)throw new ApiProblem(422,"BACKUP_INVALID","附件总容量超过备份限额，请使用不含原件的导出。");var bytes=new HashMap<String,byte[]>();if(originals)for(var file:captured.storage().values())bytes.put(file.get("id").toString(),storage.read(file.get("storageKey").toString(),((Number)file.get("sizeBytes")).longValue(),file.get("sha256").toString()));
        byte[] archive=codec.encode(owner,captured.data(),captured.files(),bytes,originals);Path staged=storage.stage(archive);String id=UUID.randomUUID().toString(),key=owner+"/"+id+".bin";boolean[] moved={false};try{return tx.execute(s->{lease(owner,payload);var user=rows.one("SELECT status,data_operation,data_revision FROM users WHERE id=:u",Map.of("u",owner),Set.of(),Set.of());if(!"ACTIVE".equals(user.get("status"))||!"IDLE".equals(user.get("dataOperation"))||((Number)user.get("dataRevision")).intValue()!=captured.revision())throw new ApiProblem(409,"DATA_REVISION_CONFLICT","导出期间数据已变化，后台将重试生成一致的备份。");storage.move(staged,key);moved[0]=true;rows.db.update("INSERT INTO files(id,user_id,purpose,original_name,storage_key,mime_type,size_bytes,sha256,expires_at) VALUES(:id,:u,'BACKUP',:name,:key,'application/zip',:size,:hash,:expires)",map("id",id,"u",owner,"name","campus-radar-backup-"+LocalDate.now(clock)+".zip","key",key,"size",archive.length,"hash",PrivateFileStorage.hash(archive),"expires",Timestamp.from(clock.instant().plus(Duration.ofDays(7)))));rows.db.update("UPDATE tasks SET result_file_id=:file WHERE id=:id AND lease_token=:lease",map("file",id,"id",payload.get("taskId"),"lease",payload.get("leaseToken")));return id;});}catch(RuntimeException failure){if(moved[0])storage.remove(key);throw failure;}finally{storage.discard(staged);}}
    private void freeze(String owner,Map<String,Object> payload,String operation){var user=rows.one("SELECT data_revision,data_operation,status FROM users WHERE id=:u",Map.of("u",owner),Set.of(),Set.of());if(!"ACTIVE".equals(user.get("status")))throw new ApiProblem(409,"ACCOUNT_INACTIVE","账号不可恢复或清空。");if(((Number)user.get("dataRevision")).intValue()!=((Number)payload.get("dataRevision")).intValue())throw new ApiProblem(409,"DATA_REVISION_CONFLICT","私人数据版本已变化。");if(!Set.of("IDLE",operation).contains(user.get("dataOperation")))throw new ApiProblem(409,"DATA_LOCKED","账号正在执行其他数据操作。");rows.db.update("UPDATE users SET data_operation=:op WHERE id=:u",map("u",owner,"op",operation));}
    @SuppressWarnings("unchecked") private String restore(String owner,Map<String,Object> payload){var preview=tx.execute(s->{lease(owner,payload);var p=rows.one("SELECT state,backup_file_id,manifest FROM import_previews WHERE user_id=:u AND id=:id",map("u",owner,"id",payload.get("previewId")),Set.of("manifest"),Set.of());if("APPLIED".equals(p.get("state")))return p;if(!Set.of("APPLYING","INVALID").contains(p.get("state")))throw new ApiProblem(409,"INVALID_STATE","恢复预览状态无效。");freeze(owner,payload,"IMPORTING");rows.db.update("UPDATE import_previews SET state='APPLYING',version=version+1 WHERE user_id=:u AND id=:id",map("u",owner,"id",payload.get("previewId")));return p;});if("APPLIED".equals(preview.get("state")))return null;
        var file=rows.one("SELECT sha256 FROM files WHERE user_id=:u AND id=:id AND state='READY'",map("u",owner,"id",preview.get("backupFileId")),Set.of(),Set.of());if(!Objects.equals(file.get("sha256"),((Map<String,Object>)preview.get("manifest")).get("backupSha256")))throw new ApiProblem(422,"BACKUP_INVALID","备份文件与预览不一致。");var archive=service.archive(owner,preview.get("backupFileId").toString());var issues=snapshots.validate(owner,archive);if(!issues.isEmpty())throw new ApiProblem(422,"BACKUP_INVALID",issues.getFirst());
        boolean includes=Boolean.TRUE.equals(archive.manifest().get("includeFiles"));var mapping=new HashMap<String,String>();var stages=new LinkedHashMap<String,Path>();var metadata=new HashMap<String,Map<String,Object>>();var moved=new ArrayList<String>();
        try{for(Object raw:(List<?>)archive.manifest().get("files")){var original=(Map<String,Object>)raw;String old=original.get("id").toString(),id=includes?UUID.randomUUID().toString():old;mapping.put(old,id);metadata.put(id,original);if(includes)stages.put(id,storage.stage(archive.files().get(old)));}
            tx.executeWithoutResult(s->{lease(owner,payload);freeze(owner,payload,"IMPORTING");var recheck=snapshots.validate(owner,archive);if(!recheck.isEmpty())throw new ApiProblem(422,"BACKUP_INVALID",recheck.getFirst());for(var entry:stages.entrySet()){String id=entry.getKey(),key=owner+"/"+id+".bin";storage.move(entry.getValue(),key);moved.add(key);var f=metadata.get(id);rows.db.update("INSERT INTO files(id,user_id,purpose,original_name,storage_key,mime_type,size_bytes,sha256) VALUES(:id,:u,:purpose,:name,:key,:mime,:size,:hash)",map("id",id,"u",owner,"purpose",f.get("purpose"),"name",f.get("name"),"key",key,"mime",f.get("mimeType"),"size",f.get("sizeBytes"),"hash",f.get("sha256")));}
                snapshots.restore(owner,archive,mapping);service.purgeMutationReplays(owner,"/api/v1/account/import-previews/"+payload.get("previewId")+"/apply");var p=map("u",owner,"keep",new ArrayList<>(mapping.values()));String keep=mapping.isEmpty()?"":" AND id NOT IN (:keep)";rows.db.update("UPDATE files SET state='PENDING_DELETE',version=version+1 WHERE user_id=:u AND purpose<>'BACKUP'"+keep,p);rows.db.update("UPDATE import_previews SET state='APPLIED',version=version+1 WHERE user_id=:u AND id=:id",map("u",owner,"id",payload.get("previewId")));applied(owner,payload);
            });return null;
        }catch(RuntimeException failure){for(String key:moved)storage.remove(key);throw failure;}finally{for(Path stage:stages.values())storage.discard(stage);}}
    private String erase(String owner,Map<String,Object> payload){boolean account="ACCOUNT".equals(payload.get("mode"));tx.executeWithoutResult(s->{lease(owner,payload);if(!account)freeze(owner,payload,"RESETTING");else {var user=rows.one("SELECT status FROM users WHERE id=:u",Map.of("u",owner),Set.of(),Set.of());if(!"DELETING".equals(user.get("status")))throw new ApiProblem(409,"INVALID_STATE","账号尚未进入注销流程。");}
            snapshots.clearPrivate(owner);var p=map("u",owner,"task",payload.get("taskId"));rows.db.update("DELETE FROM import_previews WHERE user_id=:u",p);rows.db.update("UPDATE tasks SET result_file_id=NULL WHERE user_id=:u",p);rows.db.update("UPDATE files SET state='PENDING_DELETE',version=version+1 WHERE user_id=:u",p);
            rows.db.update("UPDATE outbox_events SET state='FAILED',payload='{}',lease_token=NULL,lease_until=NULL WHERE event_type IN ('AUTH_MAIL','SUBSCRIPTION_MAIL') AND aggregate_id IN (SELECT id FROM mail_deliveries WHERE user_id=:u"+(account?"":" AND template='SUBSCRIPTION_MATCH'")+")",p);if(!account)rows.db.update("DELETE FROM mail_deliveries WHERE user_id=:u AND template='SUBSCRIPTION_MATCH'",p);if(account){eraseSocial(owner);rows.db.update("DELETE FROM auth_tokens WHERE user_id=:u",p);rows.db.update("DELETE FROM mail_deliveries WHERE user_id=:u",p);rows.db.update("DELETE FROM idempotency_records WHERE user_id=:u",p);rows.db.update("UPDATE tasks SET state=CASE WHEN id=:task THEN state ELSE 'CANCELLED' END,payload=CASE WHEN id=:task THEN payload ELSE '{}' END,error_code=NULL WHERE user_id=:u",p);}
            else {service.purgeMutationReplays(owner,"/api/v1/account/reset");rows.db.update("UPDATE users SET school=NULL,education=NULL,graduation_year=NULL,avatar_file_id=NULL,preferences=:preferences,theme='DARK',timezone='Asia/Shanghai',onboarding_step=0,buddy_discoverable=0,data_operation='IDLE',data_revision=data_revision+1,board_version=board_version+1,version=version+1 WHERE id=:u",map("u",owner,"preferences","{\"roles\":[],\"cities\":[],\"recruitmentTypes\":[],\"graduationYear\":null}"));applied(owner,payload);}
        });if(!account)return null;
        // Each physical unlink is protected by the task row lock; a reclaimed lease cannot erase files.
        for(var file:rows.query("SELECT id,storage_key FROM files WHERE user_id=:u",Map.of("u",owner)))tx.executeWithoutResult(s->{lease(owner,payload);storage.remove(file.get("storageKey").toString());rows.db.update("DELETE FROM files WHERE user_id=:u AND id=:id",map("u",owner,"id",file.get("id")));});
        tx.executeWithoutResult(s->{lease(owner,payload);applied(owner,payload);var p=map("u",owner);rows.db.update("UPDATE tasks SET user_id=NULL,dedup_key=CONCAT('erased:',id) WHERE user_id=:u",p);rows.db.update("DELETE FROM users WHERE id=:u AND status='DELETING'",p);});return null;
    }
    @Scheduled(fixedDelayString="${campus.schedule.backup-cleanup-ms:60000}") public void cleanupAbandonedFiles(){
        Instant before=clock.instant().minus(Duration.ofHours(1));try{
            for(var candidate:storage.staleObjects(before,100)){
                if(candidate.storageKey()==null){if(rows.db.queryForObject("SELECT COUNT(*) FROM tasks WHERE type IN ('DATA_EXPORT','DATA_IMPORT','USER_ERASURE') AND state IN ('QUEUED','RUNNING','RETRY_WAIT')",Map.of(),Integer.class)==0)storage.reap(candidate,before);continue;}
                String owner=candidate.storageKey().substring(0,36);tx.executeWithoutResult(s->{rows.query("SELECT id FROM users WHERE id=:u FOR UPDATE",Map.of("u",owner));if(rows.db.queryForObject("SELECT COUNT(*) FROM tasks WHERE user_id=:u AND type IN ('DATA_EXPORT','DATA_IMPORT','USER_ERASURE') AND state IN ('QUEUED','RUNNING','RETRY_WAIT')",Map.of("u",owner),Integer.class)>0)return;
                    if(rows.db.queryForObject("SELECT COUNT(*) FROM files WHERE storage_key=:key",Map.of("key",candidate.storageKey()),Integer.class)==0)storage.reap(candidate,before);
                });
            }
        }catch(org.springframework.dao.DataAccessException|ApiProblem ignored){/* Keep stale objects when metadata or the private volume is unavailable. */}
    }
    private void eraseSocial(String owner){var p=Map.of("u",owner);rows.query("SELECT id FROM buddy_rooms WHERE owner_id=:u OR id IN (SELECT room_id FROM buddy_members WHERE user_id=:u) OR id IN (SELECT room_id FROM buddy_invitations WHERE inviter_id=:u OR invitee_id=:u) ORDER BY id FOR UPDATE",p);rows.db.update("DELETE FROM referral_requests WHERE applicant_id=:u OR referral_id IN (SELECT id FROM referrals WHERE provider_id=:u)",p);rows.db.update("DELETE FROM referrals WHERE provider_id=:u",p);
        rows.db.update("DELETE FROM buddy_task_progress WHERE user_id=:u OR room_id IN (SELECT id FROM buddy_rooms WHERE owner_id=:u)",p);rows.db.update("DELETE FROM buddy_invitations WHERE inviter_id=:u OR invitee_id=:u OR room_id IN (SELECT id FROM buddy_rooms WHERE owner_id=:u)",p);rows.db.update("DELETE FROM buddy_tasks WHERE room_id IN (SELECT id FROM buddy_rooms WHERE owner_id=:u)",p);rows.db.update("DELETE FROM buddy_members WHERE user_id=:u OR room_id IN (SELECT id FROM buddy_rooms WHERE owner_id=:u)",p);rows.db.update("DELETE FROM buddy_rooms WHERE owner_id=:u",p);rows.db.update("DELETE FROM post_likes WHERE user_id=:u",p);
        rows.db.update("UPDATE experiences SET author_id=NULL,title=CASE WHEN status='PUBLISHED' THEN title ELSE '已删除内容' END,summary=CASE WHEN status='PUBLISHED' THEN summary ELSE '' END,body_md=CASE WHEN status='PUBLISHED' THEN body_md ELSE '' END,status=CASE WHEN status='PUBLISHED' THEN status ELSE 'HIDDEN' END WHERE author_id=:u",p);rows.db.update("UPDATE posts SET author_id=NULL,body_md=CASE WHEN status='PUBLISHED' THEN body_md ELSE '' END,status=CASE WHEN status='PUBLISHED' THEN status ELSE 'HIDDEN' END WHERE author_id=:u",p);rows.db.update("UPDATE comments SET author_id=NULL,body=CASE WHEN status='PUBLISHED' THEN body ELSE '' END,status=CASE WHEN status='PUBLISHED' THEN status ELSE 'HIDDEN' END WHERE author_id=:u",p);rows.db.update("UPDATE salary_reports SET author_id=NULL,source_note=CASE WHEN status='PUBLISHED' THEN source_note ELSE '' END,status=CASE WHEN status='PUBLISHED' THEN status ELSE 'HIDDEN' END WHERE author_id=:u",p);rows.db.update("DELETE FROM content_reports WHERE user_id=:u",p);rows.db.update("UPDATE content_reports SET reviewer_id=NULL,decision_note=NULL WHERE reviewer_id=:u",p);rows.db.update("UPDATE audit_logs SET actor_id=NULL,reason='账号已注销',change_summary='{}' WHERE actor_id=:u OR target_id=:u",p);rows.db.update("UPDATE audit_logs SET target_id='00000000-0000-0000-0000-000000000000' WHERE target_id=:u",p);
    }
}
